"""I/O between gsk.GShape and the C level-2 solver gl2.c (four free blocks, any abelian K)"""
import numpy as np, subprocess, os, sys, tempfile, itertools, math
HERE = os.path.dirname(os.path.abspath(__file__))
TMP = os.environ.get('GL2TMP', os.path.join(HERE, 'tmp'))
os.makedirs(TMP, exist_ok=True)


def _hplus(sh):
    """elements (unit tuples) of the group generated by H_K with phi = +1 (closure over (units, phi) pairs)"""
    Kg = sh.Kg; mods = Kg.mods
    gens = [(tuple(int(x) for x in (u if not np.isscalar(u) else [u] * len(mods))), int(ph)) for (u, ph) in sh.hgens_raw]
    one = (tuple([1] * len(mods)), 1); G = {one}; fr = [one]
    while fr:
        (x, sx) = fr.pop()
        for (g, sg) in gens:
            y = (tuple((a * b) % m for a, b, m in zip(x, g, mods)), sx * sg)
            if y not in G: G.add(y); fr.append(y)
    return [u for (u, s) in G if s == 1]


def channels(sh, maxch=128):
    """PSD channels (psi, gamma): eps = -1: psi != 0 with gamma = i sqrt(r); eps = +1: one psi of each pair {psi, -psi} with both gamma = +-sqrt(r).
    Channels equivalent under the untwisted part of H_K (|x^(psi o h)|^2 = |x^(psi)|^2 for phi(h) = +1) are merged; at most maxch channels are kept (a subset is a valid, weaker filter)."""
    Kg = sh.Kg; m = np.array(Kg.mods); N = sh.N; r = sh.r; sq = math.sqrt(r)
    el = Kg.el
    Hp = _hplus(sh)
    seen = set(); reps = []
    key = lambda c: tuple(int(x) % int(mm) for x, mm in zip(c, m))
    for a in range(1, N):
        c = key(el[a])
        if c in seen: continue
        orb = set()
        for u in Hp:
            cu = key([x * uu for x, uu in zip(c, u)]); orb.add(cu)
            if sh.eps == 1: orb.add(key([-x for x in cu]))
        seen |= orb; reps.append((len(orb), c))
    reps.sort(key=lambda t: -t[0])
    ch = []
    for (_, c) in reps:
        ang = 2 * np.pi * ((el * np.array(c)[None, :]) / m[None, :]).sum(1)
        cr, ci = np.cos(ang), np.sin(ang)
        if sh.eps == -1: ch.append((cr, ci, -sq * ci, sq * cr))
        else:
            for sg in (1, -1): ch.append((cr, ci, sg * sq * cr, sg * sq * ci))
    return ch[:maxch]


def header_text(sh):
    n = sh.N; r = sh.r; eps = sh.eps; T = sh.T2
    kI = [int(k) for k in sh.repsPM if k != 0]
    kQ = [int(k) for k in sh.repsQ]
    assert len(kI) <= 128 and len(kQ) <= 128 and n <= 640, 'shape too large for gl2.c (MAXK = 128 lags, MAXN = 640)'
    L = [f'{n} {r} {eps} {T}', str(len(kI))]
    for k in kI: L.append(' '.join(map(str, sh.shift[k])) + ' ' + ' '.join(map(str, sh.shneg[k])))
    L.append(str(len(kQ)))
    for k in kQ: L.append(' '.join(map(str, sh.shift[k])) + ' ' + ' '.join(map(str, sh.shneg[k])))
    K = sh.kCD
    for _ in range(2):
        L.append(str(K.nu))
        for i in range(K.nu):
            P = K.pos[i]
            L.append(f'{len(P)} ' + ' '.join(f'{int(p)} {int(K.sig[p])}' for p in P))
    ch = channels(sh)
    L.append(str(len(ch)))
    for (a, b, c, d) in ch:
        for arr in (a, b, c, d): L.append(' '.join(f'{x:.17g}' for x in arr))
    return '\n'.join(L) + '\n', len(ch)


def dmask(K, e):
    return [int(e[int(p[0])] != 0) for p in K.pos]


def instance_text(sh, blocks):
    L = []
    for (s, e) in blocks: L.append(' '.join(str(int(x)) for x in s))
    for b, (s, e) in enumerate(blocks): L.append(' '.join(map(str, dmask(sh.kCD, e))))
    return '\n'.join(L) + '\n'


def run_gl2(sh, insts, maxsol=5, tlimit=1e9, seed=1, maxfib=1500000, timeout=None, stop_first=False):
    """insts: list of blocks (4 x (s,e)).  returns (dict inst -> info, list of (inst idx, [t0..t3]))"""
    hdr, nch = header_text(sh)
    exe = os.path.join(HERE, 'gl2_32' if nch <= 32 else ('gl2_64' if nch <= 64 else 'gl2_128'))
    if os.environ.get('GL2_FORCE_PS'): exe = os.path.join(HERE, 'gl2_' + os.environ['GL2_FORCE_PS'])      # test hook: exercise the other builds on small shapes
    assert nch <= 128
    fd, path = tempfile.mkstemp(suffix='.gl2in', dir=TMP)
    with os.fdopen(fd, 'w') as f:
        f.write(hdr); f.write(f'{len(insts)}\n')
        for blocks in insts: f.write(instance_text(sh, blocks))
    try:
        out = subprocess.run([exe, path, str(maxsol), str(tlimit), str(seed), str(maxfib), str(int(stop_first))], capture_output=True, text=True, timeout=timeout).stdout
    finally:
        os.unlink(path)
    res = {}; sols = []
    for line in out.splitlines():
        if line.startswith('INST'):
            parts = line.split()
            i = int(parts[1]); d = dict(raw=line, compl=0, status='ok')
            for tok in parts[2:]:
                if tok.startswith('completions='): d['compl'] = int(tok.split('=')[1])
                if tok.startswith('t='): d['t'] = float(tok.split('=')[1])
                if tok in ('TIMEOUT', 'TOOBIG', 'rowfilter'): d['status'] = tok
            if len(parts) > 2 and parts[2] == 'rowfilter': d['status'] = 'rowfilter'
            if len(parts) > 2 and parts[2] == 'TOOBIG': d['status'] = 'TOOBIG'
            res[i] = d
        elif line.startswith('SOL'):
            segs = line.split('|')
            i = int(segs[0].split()[1])
            ts = [np.array([int(x) for x in sg.split()], dtype=np.int16) for sg in segs[1:5]]
            sols.append((i, ts))
    return res, sols
